ValidationRule.errorConditionFormula:
AND( ISCHANGED(StageName), (ISPICKVAL(StageName,"Verbal Commit")|| ISPICKVAL(StageName,"Closed Won")), (RecordType.Name="Initial Opportunity"|| RecordType.Name="Subsequent Opportunity"), X3_Months_Promo_calc2__c=1
)
/* If the Product's Opp is updated to Closed Won or Verbal Commit and is an Initial Opportunity or Subsequent Opportunity, The products needs to have the "3 Months Free" field input if it starts with "Tier" in the name. This is shown in the 3 Months Free Promo2 rollup with a 2. */
